CREATE POLICY "chat_img_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'chat-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "chat_img_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'chat-images');
CREATE POLICY "chat_img_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'chat-images' AND (storage.foldername(name))[1] = auth.uid()::text);